private string GetRequestQueryValue(string strKey)
{
    string strRaw = Request.RawUrl;
    if (strRaw != null && strRaw != "")
    {
        int intQueryPos = strRaw.IndexOf("?");
        if (intQueryPos >= 0)
        {
            string strQuery = strRaw.Substring(intQueryPos + 1);
            strQuery = strQuery.Replace("?", "&");

            string[] arrParts = strQuery.Split('&');
            for (int i = 0; i < arrParts.Length; i++)
            {
                int intEq = arrParts[i].IndexOf("=");
                if (intEq <= 0)
                    continue;

                string strName = arrParts[i].Substring(0, intEq).Trim();
                string strValue = arrParts[i].Substring(intEq + 1).Trim();
                if (String.Compare(strName, strKey, true) == 0)
                {
                    try
                    {
                        return Server.UrlDecode(strValue).Trim();
                    }
                    catch
                    {
                        return strValue;
                    }
                }
            }
        }
    }

    if (Request.QueryString[strKey] != null)
        return Request.QueryString[strKey].Trim();

    return "";
}

