        if (IsStudentLogin())
        {
            string strLoggedCode = GetLoggedStudentCode();
            if (strLoggedCode != "" && String.Compare(strCode, strLoggedCode, true) != 0)
                strCode = strLoggedCode;
        }

        txtStudentCode.Text = strCode;
    }

    if (IsStudentLogin())
        LoadForStudent();
    else if (strCode != "")
        LoadData();

    if (strMau != "")
        ExportByMau(strMau);
}

